RETURNING book_id;

DELETE FROM loans
WHERE returned_on IS NOT NULL
RETURNING loan_id;

SELECT name
FROM authors AS a
WHERE EXISTS (SELECT 1 FROM books AS b WHERE b.author_id = a.author_id);

SELECT name
FROM authors AS a
WHERE NOT EXISTS (SELECT 1 FROM books AS b WHERE b.author_id = a.author_id);

WITH top_books AS (
  SELECT title, rating
  FROM books
  WHERE rating >= 4.5
)
SELECT title FROM top_books ORDER BY rating DESC;
